INSERT INTO public.daily_anchors (anchor_date, tradition, theme, verse_ref, verse_text, reflection_prompt, breath_protocol) VALUES
-- Oceania / Pacific
('2026-05-18','oceania_pacific','Mana — sacred power','Māori','Your mana is your inner strength. Guard it. Build it. Never trade it for cheap things.','Where did you trade your mana for something small today? Name it.','box'),
('2026-05-19','oceania_pacific','Dadirri — deep listening','Aboriginal','Dadirri is inner, deep listening and quiet, still awareness. — Miriam-Rose Ungunmerr','Sit in silence for five minutes. What did the quiet teach you?','4-7-8'),
('2026-05-20','oceania_pacific','Aloha — breath of life','Hawaiian','Aloha: alo (presence) + ha (breath). To greet is to share breath, to share life.','Who did you meet today without truly being present? Name them.','4-7-8'),
('2026-05-21','oceania_pacific','Whakapapa — ancestral line','Māori','You are not one man. You are every ancestor who survived so you could stand here.','Which ancestor''s strength did you draw on today, knowingly or not?','box'),
('2026-05-22','oceania_pacific','Songlines — walk your path','Aboriginal','The land remembers every footstep. Walk yours with care.','What path are you walking that your descendants will trace? Is it true?','4-7-8'),
('2026-05-23','oceania_pacific','Ho''oponopono — make it right','Hawaiian','I''m sorry. Please forgive me. Thank you. I love you. Four sentences. Use them.','To whom — including yourself — do you owe these four sentences today?','box'),
('2026-05-24','oceania_pacific','Tapu and noa — sacred and free','Polynesian','Some things are tapu — sacred, set apart. Some are noa — free, ordinary. Know which is which.','What in your life have you been treating as ordinary that is actually sacred?','4-7-8'),

-- African Traditional
('2026-05-18','african_traditional','Ubuntu — I am because we are','Zulu / Xhosa','Umuntu ngumuntu ngabantu — a person is a person through other people.','Who made you who you are today? Have you thanked them lately?','4-7-8'),
('2026-05-19','african_traditional','Iwa pele — gentle character','Yoruba / Ifá','Iwa l''ewa — character is beauty. The most beautiful thing about a person is their character.','Where did your character slip today? Where did it hold?','box'),
('2026-05-20','african_traditional','Ase — the power to make things happen','Yoruba','Ase is the spark of creation in your tongue. Speak only what you want to build.','What did you speak today that you should not have? What will you speak tomorrow that builds?','4-7-8'),
('2026-05-21','african_traditional','Sankofa — go back and fetch it','Akan','Se wo were fi na wosankofa a yenkyi — it is not wrong to go back for that which you have forgotten.','What part of yourself did you leave behind that you need to go back for?','box'),
('2026-05-22','african_traditional','Ancestors at your back',NULL,'Your ancestors are not behind you. They are within you. They breathe when you breathe.','When you stood at a hard moment today, who stood with you? Speak their name.','4-7-8'),
('2026-05-23','african_traditional','Ori — your inner head','Yoruba','Your Ori is your destiny, the part of you that chose this life. Listen to it before you ask the world.','What did your Ori — your deepest knowing — tell you today that you ignored?','box'),
('2026-05-24','african_traditional','Communal table',NULL,'In our tradition, no one eats alone. The meal is medicine, and the company is the cure.','Who did you eat with today? If alone — who could you have shared a meal with?','4-7-8'),

-- Sufi
('2026-05-18','sufi','The wound is the light','Rumi','The wound is the place where the Light enters you.','Name the wound you''ve been hiding. Where might it be a door?','4-7-8'),
('2026-05-19','sufi','Die before you die','Hadith / Sufi','Die before you die, and you will not die when you die.','What part of the old you needs to die today so the truer you can live?','box'),
('2026-05-20','sufi','Polish the heart','Rumi','The heart is a mirror. Every wrong act dulls it. Every dhikr polishes it.','What dulled your heart today? What single act of remembrance can polish it tonight?','4-7-8'),
('2026-05-21','sufi','Be a lamp','Hafiz','I wish I could show you, when you are lonely or in darkness, the astonishing light of your own being.','When did you forget your own light today? Who reminded you — or could have?','box'),
('2026-05-22','sufi','Fana — annihilation of ego','Ibn Arabi','Until the ego is dissolved, the Beloved is not seen.','Where did your ego run the show today? What would the no-ego version have done?','4-7-8'),
('2026-05-23','sufi','Dhikr — the breath of remembrance',NULL,'On the inhale: La ilaha. On the exhale: illa Allah. Let the breath itself be prayer.','Twenty conscious breaths with remembrance. What shifted inside you?','box'),
('2026-05-24','sufi','The guest house','Rumi','This being human is a guest house. Every morning a new arrival. Welcome them all.','What guest — grief, joy, fear — knocked today? Did you welcome it or slam the door?','4-7-8'),

-- Sikh
('2026-05-18','sikh','Ik Onkar — one with all','Mool Mantar','Ik Onkar — there is one creative force, present in all.','Where did you treat someone today as separate from you? How does that look from oneness?','4-7-8'),
('2026-05-19','sikh','Seva — selfless service','Guru Granth Sahib','He who performs selfless service, without thought of reward, shall attain the Lord.','One act of seva today, with no audience and no reward. Name it. If none — plan tomorrow''s.','box'),
('2026-05-20','sikh','Chardi Kala — rising spirits','Sikh tradition','Chardi Kala — eternal optimism, even in the darkest hour. The spirit rises no matter what.','What heavy news met you today? How can chardi kala answer it without lying to yourself?','4-7-8'),
('2026-05-21','sikh','Naam Simran — remembrance of the Name','Guru Nanak','He who meditates on the Naam, his body becomes pure, his mind becomes pure.','Three minutes of silent remembrance — one word, repeated with the breath. What word did you choose?','box'),
('2026-05-22','sikh','Kirat Karni — honest work','Guru Nanak','Earn your living by honest work, share with others, remember the Divine.','Was every dollar you earned today clean? Was every hour given honestly?','4-7-8'),
('2026-05-23','sikh','The five thieves','Sikh teaching','Kam (lust), krodh (anger), lobh (greed), moh (attachment), ahankar (ego) — these five rob the soul.','Which of the five thieves visited you today? What did you let them take?','box'),
('2026-05-24','sikh','Sangat — the company you keep','Guru Granth Sahib','In the company of the holy, even the dull mind becomes radiant.','Who is in your sangat — your closest five? Are they pulling you up or down?','4-7-8');